import { test, expect } from '@playwright/test';
import { resetAndSeed } from '../support/seed';

// follow.
//   gust: Ada 30+66=96, Ben -3-4=-7, Dot 100+200=300
//   coil: Ada 96-15=81, Ben -7-(-1)=-6, Dot 300-100=200 ; total 96-7+300=389

test.describe('gust coefficient raised to 2', () => {
  test('gust = reach + 2*torque; coil and total follow', { tag: '@functionality' }, async ({ page }) => {
    await resetAndSeed({
  people: [
    { id: 1, name: 'Ada', alpha: 2, beta: 3,  gamma: 5, delta: 3, epsilon: 4,  zeta: 10, active: true },
    { id: 2, name: 'Ben', alpha: 4, beta: 2,  gamma: 1, delta: 5, epsilon: 2,  zeta: 1,  active: true },
    { id: 3, name: 'Dot', alpha: 5, beta: 20, gamma: 5, delta: 5, epsilon: 20, zeta: 5,  active: true },
  ],
  regions: [
    { personId: 1, region: 'N1' }, { personId: 2, region: 'S2' }, { personId: 3, region: 'E5' },
  ],
});
    await page.goto('/');

    await expect(page.getByTestId('person-row-1').getByTestId('concept-gust')).toHaveText('96');
    await expect(page.getByTestId('person-row-2').getByTestId('concept-gust')).toHaveText('-7');
    await expect(page.getByTestId('person-row-3').getByTestId('concept-gust')).toHaveText('300');

    await expect(page.getByTestId('person-row-1').getByTestId('concept-coil')).toHaveText('81');
    await expect(page.getByTestId('person-row-2').getByTestId('concept-coil')).toHaveText('-6');
    await expect(page.getByTestId('person-row-3').getByTestId('concept-coil')).toHaveText('200');

    await expect(page.getByTestId('rollup-total-gust')).toHaveText('389');
  });
});
